-- Premium topic choices and selected-topic persistence.
-- Generated from scripts/premium-topic-manifest.mjs. Do not edit topic JSON here.

alter table public.review_premium_tasks
  add column if not exists topics jsonb not null default '[]'::jsonb;

alter table public.review_task_submissions
  add column if not exists selected_topic_key text;

do $constraints$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.review_premium_tasks'::regclass
      and conname = 'review_premium_tasks_topics_array'
  ) then
    alter table public.review_premium_tasks
      add constraint review_premium_tasks_topics_array
      check (jsonb_typeof(topics) = 'array');
  end if;
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.review_task_submissions'::regclass
      and conname = 'review_task_submissions_topic_key_length'
  ) then
    alter table public.review_task_submissions
      add constraint review_task_submissions_topic_key_length
      check (selected_topic_key is null or length(btrim(selected_topic_key)) between 1 and 100);
  end if;
end;
$constraints$;

do $topics$
declare
  updated_count integer;
begin
  with source(slug, topics) as (
    values
    ('june-28', '[{"key":"cafe-order","title_en":"A café order","title_ja":"カフェでの注文","description_en":"A café order you would enjoy and how you would ask politely.","description_ja":"カフェで楽しみたい注文と、丁寧な頼み方","speaking_prompt_en":"Speak for 60–90 seconds about a café order you would enjoy and how you would ask politely. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"カフェで楽しみたい注文と、丁寧な頼み方について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a café order you would enjoy and how you would ask politely. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"カフェで楽しみたい注文と、丁寧な頼み方について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I’d like …, please.","Could I have …?","That’s all, thank you."],"vocabulary":["order","recommendation","decaf","takeaway"]},{"key":"polite-decline","title_en":"A polite no","title_ja":"丁寧な断り方","description_en":"A time you needed to decline an invitation without sounding unfriendly.","description_ja":"相手を嫌な気持ちにさせず、誘いを断った経験","speaking_prompt_en":"Speak for 60–90 seconds about a time you needed to decline an invitation without sounding unfriendly. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"相手を嫌な気持ちにさせず、誘いを断った経験について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a time you needed to decline an invitation without sounding unfriendly. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"相手を嫌な気持ちにさせず、誘いを断った経験について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["Thank you, but …","I’m afraid I can’t.","Maybe another time."],"vocabulary":["invitation","schedule","decline","alternative"]},{"key":"customer-care","title_en":"Good customer service","title_ja":"良い接客","description_en":"What makes service at a café or shop feel thoughtful and welcoming.","description_ja":"カフェや店で、気配りのある接客だと感じること","speaking_prompt_en":"Speak for 60–90 seconds about what makes service at a café or shop feel thoughtful and welcoming. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"カフェや店で、気配りのある接客だと感じることについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about what makes service at a café or shop feel thoughtful and welcoming. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"カフェや店で、気配りのある接客だと感じることについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["How can I help?","Would you like anything else?","I appreciate it."],"vocabulary":["service","welcoming","attentive","request"]}]'::jsonb),
    ('june-29', '[{"key":"misheard-message","title_en":"A message you misheard","title_ja":"聞き間違えたメッセージ","description_en":"A misunderstanding caused by hearing one word or detail incorrectly.","description_ja":"単語や細部の聞き間違いから生まれた誤解","speaking_prompt_en":"Speak for 60–90 seconds about a misunderstanding caused by hearing one word or detail incorrectly. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"単語や細部の聞き間違いから生まれた誤解について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a misunderstanding caused by hearing one word or detail incorrectly. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"単語や細部の聞き間違いから生まれた誤解について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I thought you said …","Could you say that again?","Now I understand."],"vocabulary":["misunderstanding","detail","clarify","announcement"]},{"key":"surprising-news","title_en":"Surprising news","title_ja":"驚いた知らせ","description_en":"News that surprised you and how you reacted when you first heard it.","description_ja":"驚いた知らせと、それを初めて聞いたときの反応","speaking_prompt_en":"Speak for 60–90 seconds about news that surprised you and how you reacted when you first heard it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"驚いた知らせと、それを初めて聞いたときの反応について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about news that surprised you and how you reacted when you first heard it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"驚いた知らせと、それを初めて聞いたときの反応について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I couldn’t believe it.","That was unexpected.","I heard that …"],"vocabulary":["reaction","rumour","confirmed","unexpected"]},{"key":"finding-position","title_en":"Finding the right place","title_ja":"場所を見つける","description_en":"How you would explain where a person or object is positioned.","description_ja":"人や物がどこにあるかを、分かりやすく説明する方法","speaking_prompt_en":"Speak for 60–90 seconds about how you would explain where a person or object is positioned. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"人や物がどこにあるかを、分かりやすく説明する方法について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about how you would explain where a person or object is positioned. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"人や物がどこにあるかを、分かりやすく説明する方法について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["It’s next to …","You’ll see it on your left.","It’s directly behind …"],"vocabulary":["position","opposite","beside","landmark"]}]'::jsonb),
    ('june-30', '[{"key":"stadium-feelings","title_en":"A memorable match","title_ja":"印象に残った試合","description_en":"A sports match that changed your mood while you were watching it.","description_ja":"見ている間に気持ちが変化した、印象的なスポーツの試合","speaking_prompt_en":"Speak for 60–90 seconds about a sports match that changed your mood while you were watching it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"見ている間に気持ちが変化した、印象的なスポーツの試合について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a sports match that changed your mood while you were watching it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"見ている間に気持ちが変化した、印象的なスポーツの試合について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I was excited when …","It was frustrating because …","In the end, …"],"vocabulary":["supporter","equaliser","frustrated","atmosphere"]},{"key":"everyday-annoyance","title_en":"An everyday annoyance","title_ja":"日常のちょっとした不満","description_en":"A small everyday problem that annoys you and a reasonable solution.","description_ja":"日常で少し困ることと、現実的な解決方法","speaking_prompt_en":"Speak for 60–90 seconds about a small everyday problem that annoys you and a reasonable solution. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"日常で少し困ることと、現実的な解決方法について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a small everyday problem that annoys you and a reasonable solution. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"日常で少し困ることと、現実的な解決方法について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I’m annoyed by …","What bothers me is …","It would help if …"],"vocabulary":["noise","habit","solution","considerate"]},{"key":"personal-preference","title_en":"A preference that matters","title_ja":"大切にしている好み","description_en":"A choice where your personal preference is stronger than other people’s advice.","description_ja":"周りの意見より、自分の好みを大切にした選択","speaking_prompt_en":"Speak for 60–90 seconds about a choice where your personal preference is stronger than other people’s advice. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"周りの意見より、自分の好みを大切にした選択について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a choice where your personal preference is stronger than other people’s advice. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"周りの意見より、自分の好みを大切にした選択について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["I prefer … to …","For me, … works better.","It depends on …"],"vocabulary":["preference","priority","option","recommendation"]}]'::jsonb),
    ('july-04', '[{"key":"unexpected-delay","title_en":"When plans changed","title_ja":"予定が変わったとき","description_en":"An unexpected delay or problem that changed your plans.","description_ja":"予想外の遅れや問題で、予定が変わった経験","speaking_prompt_en":"Speak for 60–90 seconds about an unexpected delay or problem that changed your plans. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"予想外の遅れや問題で、予定が変わった経験について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about an unexpected delay or problem that changed your plans. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"予想外の遅れや問題で、予定が変わった経験について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["Something came up.","I ended up …","Luckily, …"],"vocabulary":["delay","reschedule","unexpected","manage"]},{"key":"helpful-stranger","title_en":"Help at the right moment","title_ja":"助けてもらった瞬間","description_en":"A time someone helped you when everyday life did not go as planned.","description_ja":"日常が思いどおりにいかないとき、誰かに助けてもらった経験","speaking_prompt_en":"Speak for 60–90 seconds about a time someone helped you when everyday life did not go as planned. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"日常が思いどおりにいかないとき、誰かに助けてもらった経験について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a time someone helped you when everyday life did not go as planned. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"日常が思いどおりにいかないとき、誰かに助けてもらった経験について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I was having trouble with …","Someone offered to …","It made a difference."],"vocabulary":["assistance","kindness","situation","relieved"]},{"key":"backup-plan","title_en":"Your backup plan","title_ja":"自分の予備プラン","description_en":"How you prepare a practical backup plan for work, travel or daily life.","description_ja":"仕事・旅行・