    ('july-27', '[{"key":"small-accident","title_en":"A small accident","title_ja":"小さなアクシデント","description_en":"A small spill, splash or mistake and how you dealt with it.","description_ja":"こぼす・水がかかるなどの小さな失敗と、その後の対応","speaking_prompt_en":"Speak for 60–90 seconds about a small spill, splash or mistake and how you dealt with it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"こぼす・水がかかるなどの小さな失敗と、その後の対応について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a small spill, splash or mistake and how you dealt with it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"こぼす・水がかかるなどの小さな失敗と、その後の対応について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I accidentally spilled …","It splashed onto …","I cleaned it up by …"],"vocabulary":["spill","pour","splash","accidentally"]},{"key":"acquired-taste","title_en":"An acquired taste","title_ja":"だんだん好きになったもの","description_en":"A food, drink or activity you learned to enjoy gradually.","description_ja":"少しずつ好きになった食べ物・飲み物・活動","speaking_prompt_en":"Speak for 60–90 seconds about a food, drink or activity you learned to enjoy gradually. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"少しずつ好きになった食べ物・飲み物・活動について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a food, drink or activity you learned to enjoy gradually. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"少しずつ好きになった食べ物・飲み物・活動について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["It is an acquired taste.","I didn’t like it at first.","Now I appreciate …"],"vocabulary":["flavour","bitter","gradually","appreciate"]},{"key":"tense-story","title_en":"Telling the full story","title_ja":"時制を使い分ける物語","description_en":"A short story that clearly connects what happened before, during and afterward.","description_ja":"出来事の前・最中・その後を、時制を分けて伝える短い話","speaking_prompt_en":"Speak for 60–90 seconds about a short story that clearly connects what happened before, during and afterward. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"出来事の前・最中・その後を、時制を分けて伝える短い話について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a short story that clearly connects what happened before, during and afterward. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"出来事の前・最中・その後を、時制を分けて伝える短い話について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["Before that, I had …","While I was …","Since then, I have …"],"vocabulary":["sequence","background","result","timeline"]}]'::jsonb)
  )
  update public.review_premium_tasks t
  set topics = source.topics,
      updated_at = now()
  from public.review_lessons l, source
  where t.lesson_id = l.id
    and l.slug = source.slug
    and t.stable_key in (
      l.slug || '-premium-speaking-v1',
      l.slug || '-premium-essay-v1'
    );
  get diagnostics updated_count = row_count;
  if updated_count <> 34 then
    raise exception 'Premium topic update incomplete: expected 34 tasks, updated %.', updated_count;
  end if;
end;
$topics$;

create or replace function public.review_validate_submission_topic()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare
  task_topics jsonb;
begin
  select t.topics into task_topics
  from public.review_premium_tasks t
  where t.id = new.task_id;

  task_topics := coalesce(task_topics, '[]'::jsonb);
  if new.selected_topic_key is not null and not exists (
    select 1
    from jsonb_array_elements(task_topics) item
    where item ->> 'key' = btrim(new.selected_topic_key)
  ) then
    raise exception 'Choose a topic offered for this Premium task.';
  end if;

  if new.status = 'submitted'
     and jsonb_array_length(task_topics) > 0
     and nullif(btrim(coalesce(new.selected_topic_key, '')), '') is null then
    raise exception 'Choose a topic before submitting this Premium task.';
  end if;

  if tg_op = 'UPDATE'
     and old.status not in ('draft', 'returned')
     and new.selected_topic_key is distinct from old.selected_topic_key then
    raise exception 'The selected topic is locked while the teacher reviews this submission.';
  end if;
  return new;
end;
$function$;

revoke all on function public.review_validate_submission_topic() from public;

drop trigger if exists review_task_submissions_topic_validate
  on public.review_task_submissions;
create trigger review_task_submissions_topic_validate
before insert or update on public.review_task_submissions
for each row execute function public.review_validate_submission_topic();

do $verify$
declare
  covered_tasks integer;
  invalid_topics integer;
  invalid_topic_sets integer;
begin
  select count(*) into covered_tasks
  from public.review_premium_tasks t
  join public.review_lessons l on l.id = t.lesson_id
  where t.active
    and t.stable_key in (
      l.slug || '-premium-speaking-v1',
      l.slug || '-premium-essay-v1'
    )
    and jsonb_array_length(t.topics) = 3;

  select count(*) into invalid_topics
  from public.review_premium_tasks t
  join public.review_lessons l on l.id = t.lesson_id
  cross join lateral jsonb_array_elements(t.topics) item
  where t.active
    and t.stable_key in (
      l.slug || '-premium-speaking-v1',
      l.slug || '-premium-essay-v1'
    )
    and (
      jsonb_typeof(item) <> 'object'
      or nullif(btrim(item ->> 'key'), '') is null
      or nullif(btrim(item ->> 'title_en'), '') is null
      or nullif(btrim(item ->> 'title_ja'), '') is null
      or nullif(btrim(item ->> 'description_en'), '') is null
      or nullif(btrim(item ->> 'description_ja'), '') is null
      or nullif(btrim(item ->> 'speaking_prompt_en'), '') is null
      or nullif(btrim(item ->> 'speaking_prompt_ja'), '') is null
      or nullif(btrim(item ->> 'essay_prompt_en'), '') is null
      or nullif(btrim(item ->> 'essay_prompt_ja'), '') is null
      or jsonb_typeof(item -> 'phrases') <> 'array'
      or jsonb_array_length(item -> 'phrases') not between 3 and 6
      or jsonb_typeof(item -> 'vocabulary') <> 'array'
      or jsonb_array_length(item -> 'vocabulary') not between 3 and 8
    );

  select count(*) into invalid_topic_sets
  from public.review_premium_tasks t
  join public.review_lessons l on l.id = t.lesson_id
  where t.active
    and t.stable_key in (
      l.slug || '-premium-speaking-v1',
      l.slug || '-premium-essay-v1'
    )
    and (
      jsonb_array_length(t.topics) <> 3
      or (select count(distinct item ->> 'key') from jsonb_array_elements(t.topics) item) <> 3
    );

  if covered_tasks <> 34 or invalid_topics <> 0 or invalid_topic_sets <> 0 then
    raise exception 'Premium topic verification failed: covered %, invalid topics %, invalid sets %.',
      covered_tasks, invalid_topics, invalid_topic_sets;
  end if;
end;
$verify$;

comment on column public.review_premium_tasks.topics is
  'Learner-safe bilingual topic choices with topic-specific prompts, phrases and vocabulary.';
comment on column public.review_task_submissions.selected_topic_key is
  'The stable topic chosen by the learner for this attempt.';
